@php
    /*
     * Hero opportunity map. Geography is real (US Atlas); the glowing points are ILLUSTRATIVE sample
     * locations generated by scripts/generate-us-map.mjs, not real listings.
     */
    $map = once(fn () => json_decode(file_get_contents(resource_path('data/us-map.json')), true));

    $regionOf = [
        'northeast' => ['NY', 'MA', 'CT', 'PA', 'MD', 'DC', 'VA'],
        'southeast' => ['NC', 'SC', 'GA', 'FL', 'TN', 'AL', 'LA', 'KY'],
        'midwest' => ['OH', 'MI', 'IN', 'IL', 'WI', 'MN', 'IA', 'MO', 'NE', 'KS', 'ND', 'SD'],
        'south_central' => ['TX', 'OK'],
        'west' => ['CO', 'UT', 'AZ', 'NV', 'ID', 'CA', 'OR', 'WA', 'MT', 'NM'],
    ];
    $labels = [
        'northeast' => 'Northeast & Mid-Atlantic',
        'southeast' => 'Southeast',
        'midwest' => 'Midwest',
        'south_central' => 'South Central',
        'west' => 'West',
    ];

    $points = collect($map['points'])->map(function ($p) use ($regionOf) {
        $p['region'] = collect($regionOf)->search(fn ($states) => in_array($p['state'], $states, true));
        return $p;
    });

    // Per-region summary computed from the sample points only.
    $summaries = [];
    foreach ($labels as $key => $label) {
        $inRegion = $points->where('region', $key);
        $top = $inRegion->countBy('industry')->sortDesc()->keys()->first();
        $summaries[$key] = [
            'label' => $label,
            'count' => $inRegion->count(),
            'industry' => $top,
        ];
    }
@endphp

<div x-data="usMap(@js($summaries))" {{ $attributes->class(['relative']) }}>
    <div class="relative">
        <svg
            viewBox="{{ $map['viewBox'] }}"
            class="h-auto w-full"
            role="img"
            aria-label="Map of the continental United States with sample acquisition opportunity points. Illustrative data."
        >
            <defs>
                <filter id="nk-glow" x="-200%" y="-200%" width="500%" height="500%">
                    <feGaussianBlur stdDeviation="5"/>
                </filter>
                <linearGradient id="nk-land" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0" stop-color="#1b604a" stop-opacity="0.55"/>
                    <stop offset="1" stop-color="#10291f" stop-opacity="0.35"/>
                </linearGradient>
            </defs>

            <path d="{{ $map['statesPath'] }}" fill="url(#nk-land)"/>
            <path d="{{ $map['bordersPath'] }}" fill="none" stroke="#c99b43" stroke-opacity="0.22" stroke-width="0.6" stroke-linejoin="round"/>

            @foreach ($points as $p)
                @php $r = [1 => 2.2, 2 => 3, 3 => 4][$p['intensity']]; @endphp
                <g
                    class="map-point cursor-pointer transition-opacity duration-300"
                    :class="isActive('{{ $p['region'] }}') ? 'opacity-100' : 'opacity-15'"
                    @mouseenter="hover = @js(['city' => $p['city'], 'state' => $p['state'], 'industry' => $p['industry'], 'x' => $p['x'], 'y' => $p['y']])"
                    @mouseleave="hover = null"
                    @click="select('{{ $p['region'] }}')"
                >
                    <circle cx="{{ $p['x'] }}" cy="{{ $p['y'] }}" r="{{ $r * 2.4 }}" fill="#e3c27d" opacity="0.5" filter="url(#nk-glow)"/>
                    @if ($p['intensity'] === 3)
                        <circle cx="{{ $p['x'] }}" cy="{{ $p['y'] }}" r="{{ $r * 2 }}" fill="#e3c27d" class="map-point animate-pulse-point" style="animation-delay: {{ ($p['id'] % 7) * 0.45 }}s"/>
                    @endif
                    <circle cx="{{ $p['x'] }}" cy="{{ $p['y'] }}" r="{{ $r }}" fill="#f6dc9b"/>
                    {{-- larger invisible hit area for touch --}}
                    <circle cx="{{ $p['x'] }}" cy="{{ $p['y'] }}" r="12" fill="transparent"/>
                </g>
            @endforeach
        </svg>

        <div
            x-show="hover" x-cloak x-transition.opacity.duration.150ms
            class="pointer-events-none absolute z-10 -translate-x-1/2 -translate-y-[130%] whitespace-nowrap rounded-xl border border-gold/40 bg-forest-deep/95 px-3 py-2 text-xs shadow-xl"
            :style="hover ? `left:${hover.x / 9.6}%; top:${hover.y / 6}%` : ''"
        >
            <p class="font-semibold text-ivory" x-text="hover ? `${hover.city}, ${hover.state}` : ''"></p>
            <p class="text-gold-soft" x-text="hover ? `${hover.industry} · sample` : ''"></p>
        </div>
    </div>

    <div class="lg:max-w-[52%]">
    <div class="mt-3 flex flex-wrap items-center gap-2" role="group" aria-label="Filter sample opportunities by region">
        @foreach ($labels as $key => $label)
            <button
                type="button"
                @click="select('{{ $key }}')"
                :aria-pressed="(region === '{{ $key }}').toString()"
                :class="region === '{{ $key }}' ? 'border-gold bg-gold text-forest-deep' : 'border-ivory/25 text-ivory/80 hover:border-gold hover:text-gold-soft'"
                class="rounded-full border px-3.5 py-1.5 text-xs font-medium transition"
            >{{ $label }}</button>
        @endforeach
    </div>

    <p class="mt-3 min-h-10 text-xs text-ivory/70" aria-live="polite">
        <template x-if="summary">
            <span>
                <span class="font-semibold text-gold-soft" x-text="summary.label"></span>:
                <span x-text="summary.count"></span> sample opportunities, most common sector
                <span x-text="summary.industry"></span>.
            </span>
        </template>
        <template x-if="!summary">
            <span>Choose a region to see its sample insight. All points are illustrative, not live listings.</span>
        </template>
    </p>
    </div>
</div>
